-- KO-225 group 2 missing body_id translation batch 3

update public.content_variants set body = $json${"text":"Rina buys a new token whose name is similar to a famous coin. Turns out it was a fake token. The price immediately dropped from IDR 50,000 to almost zero. He lost IDR 1,000,000 in one night."}$json$::jsonb, body_id = $json${"text":"Rina membeli token baru yang namanya mirip dengan koin terkenal. Ternyata itu token palsu. Harganya langsung turun dari Rp 50.000 menjadi hampir nol. Ia kehilangan Rp 1.000.000 dalam satu malam."}$json$::jsonb where id = '32897b1f-4ca4-44f9-b1ac-10a9351f419d';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"Paying only the minimum on high-interest debt is the fastest way to become debt free.","difficulty":"beginner","explanation":"Minimum payments let interest continue to accrue, making the debt last longer and cost more."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Membayar hanya minimum pada utang berbunga tinggi adalah cara tercepat bebas utang.","difficulty":"beginner","explanation":"Pembayaran minimum membiarkan bunga terus bertambah, sehingga utang berlangsung lebih lama dan lebih mahal."}$json$::jsonb where id = '36ac16b9-d178-4a6d-8f6a-d0e2e1c1550e';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Hiding full costs and encouraging impulse purchases","options":["Hiding full costs and encouraging impulse purchases","Always illegal","There are never any flowers","Can only be used for necessities"],"question":"Why is PayLater dangerous for desire?","difficulty":"beginner","explanation":"PayLater breaks down payments so they feel cheap, even though the total can be inflated and often triggers unplanned purchases."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Menyembunyikan biaya penuh dan mendorong pembelian impulsif","options":["Menyembunyikan biaya penuh dan mendorong pembelian impulsif","Selalu ilegal","Tidak pernah ada bunga","Hanya bisa dipakai untuk kebutuhan"],"question":"Mengapa PayLater berbahaya untuk keinginan?","difficulty":"beginner","explanation":"PayLater memecah pembayaran sehingga terasa murah, padahal total bisa membengkak dan sering memicu pembelian yang tidak direncanakan."}$json$::jsonb where id = '37a80a79-209c-45ce-8a14-31765d96298c';
update public.content_variants set body = $json${"text":"Bayu keeps a small portion of his crypto in a cold wallet after purchasing. He stores the recovery phrase in a safe place separate from the device, because if the phrase is lost, the crypto can no longer be accessed."}$json$::jsonb, body_id = $json${"text":"Bayu menyimpan sebagian kecil kriptonya di cold wallet setelah membeli. Ia menyimpan frasa pemulihan di tempat aman yang terpisah dari perangkatnya, karena jika frasa itu hilang, kriptonya tidak bisa diakses lagi."}$json$::jsonb where id = '387a3c20-fb7f-4286-81e7-5d7b228365d7';
update public.content_variants set body = $json${"text":"Sari sets aside IDR 300,000 per month for index mutual funds as a long-term investment. He separated that from the Rp. 200,000 in speculation money he was willing to lose to try crypto. Food and boarding fees are not touched."}$json$::jsonb, body_id = $json${"text":"Sari menyisihkan Rp 300.000 per bulan untuk reksa dana indeks sebagai investasi jangka panjang. Ia memisahkan itu dari uang spekulasi Rp 200.000 yang rela hilang untuk mencoba kripto. Uang makan dan kosnya tidak disentuh."}$json$::jsonb where id = '3ca15970-f57e-4e2a-a4d6-a7728b9bca6a';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"You can use Bitcoin to pay taxes or buy coffee at an Indonesian shop like rupiah.","difficulty":"beginner","explanation":"Crypto is not a legal means of payment in Indonesia. Official transactions must use rupiah."}$json$::jsonb, body_id = $json${"type":"true_false","answer":false,"question":"Kamu bisa menggunakan Bitcoin untuk membayar pajak atau membeli kopi di warung Indonesia seperti uang rupiah.","difficulty":"beginner","explanation":"Kripto bukan alat pembayaran yang sah di Indonesia. Transaksi resmi harus menggunakan rupiah."}$json$::jsonb where id = '3cfbec52-8c83-42cd-a0f6-e77e0ac4cca0';
update public.content_variants set body = $json${"text":"Bayu just started working with a salary of IDR 6,000,000/month. He opened a BCA Stages account for salary and expenses, then opened a deposit of IDR 2,000,000 for emergency funds. Every month, he automatically transfers IDR 500,000 from his savings account to his deposit. In a year, the emergency fund is IDR 6,000,000 (3 months of expenses)."}$json$::jsonb, body_id = $json${"text":"Bayu baru mulai kerja dengan gaji Rp 6.000.000/bulan. Dia buka rekening BCA Tahapan untuk gaji dan pengeluaran, lalu buka deposito Rp 2.000.000 untuk dana darurat. Setiap bulan, dia auto-transfer Rp 500.000 dari rekening tabungan ke deposito. Dalam setahun, dana daruratnya Rp 6.000.000 (3 bulan pengeluaran)."}$json$::jsonb where id = '3db99bf5-e20b-4f3d-8945-73723858f8dd';
update public.content_variants set body = $json${"type":"fill_blank","answer":"RDN","question":"To buy ETFs on IDX, you must open a _____ account.","difficulty":"beginner","explanation":"RDN (Customer Fund Account) is a special account in securities used for trading shares and ETFs on the Indonesian Stock Exchange."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"RDN","question":"Untuk membeli ETF di IDX, kamu harus membuka rekening _____.","difficulty":"beginner","explanation":"RDN (Rekening Dana Nasabah) adalah rekening khusus di sekuritas yang digunakan untuk trading saham dan ETF di Bursa Efek Indonesia."}$json$::jsonb where id = '3e7297dd-03fb-452a-800a-865a4888c2b1';
update public.content_variants set body = $json${"type":"fill_blank","answer":"increase","question":"Debt used to buy something that _____ your future income or wealth is usually called good debt.","difficulty":"beginner","explanation":"Good debt contributes to long-term financial growth, not just satisfying momentary desires."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"meningkatkan","question":"Utang yang digunakan untuk membeli sesuatu yang _____ penghasilan atau kekayaan masa depanmu biasanya disebut utang baik.","difficulty":"beginner","explanation":"Utang baik berkontribusi pada pertumbuhan keuangan jangka panjang, bukan hanya memuaskan keinginan sesaat."}$json$::jsonb where id = '45085474-605c-487e-b691-6b57973308ca';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Cold wallets","options":["Cold wallets","Hot wallets on exchanges","Ordinary paper wallet","Bank savings account"],"question":"The most secure crypto wallet from hacking but at risk of losing access if the recovery phrase is lost is...","difficulty":"beginner","explanation":"Cold wallets store crypto offline so they are difficult to hack, but losing the recovery phrase can mean access is lost forever."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Cold wallet","options":["Cold wallet","Hot wallet di bursa","Dompet kertas biasa","Rekening tabungan bank"],"question":"Dompet kripto yang paling aman dari peretasan namun berisiko hilang akses jika frasa pemulihannya hilang adalah...","difficulty":"beginner","explanation":"Cold wallet menyimpan kripto secara offline sehingga sulit diretas, tetapi kehilangan frasa pemulihan bisa membuat akses hilang selamanya."}$json$::jsonb where id = '458ea585-8788-4ce0-9467-abeae1a5fd10';

